import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const $=s=>document.querySelector(s), canvas=$('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x080a0c);scene.fog=new THREE.FogExp2(0x080a0c,.027);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,100);let camYaw=0;
scene.add(new THREE.HemisphereLight(0x8493a2,0x15110d,.34));
const fill=new THREE.DirectionalLight(0x8c9aaa,.55);fill.position.set(-7,12,4);fill.castShadow=true;fill.shadow.mapSize.set(1024,1024);fill.shadow.camera.left=-28;fill.shadow.camera.right=28;fill.shadow.camera.top=28;fill.shadow.camera.bottom=-28;scene.add(fill);
const mat=(color,rough=.86,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mFloor=[mat(0x292a28),mat(0x302f2b),mat(0x262725)],mWall=[mat(0x393631),mat(0x302e2a),mat(0x403b35)],mTrim=mat(0x51483b),mDark=mat(0x171719),mGold=mat(0x927341,.48,.55);
const grid=[
'#############','#....#......#','#....#......#','#...........#','#..#....#...#','#..#....#...#','#..#........#','#......#....#','#......#....#','#....#......#','#....#......#','#...........#','#############'];
const N=13,CELL=4,world=(r,c)=>new THREE.Vector3((c-6)*CELL,0,(r-6)*CELL),walk=(r,c)=>r>=0&&c>=0&&r<N&&c<N&&grid[r][c]==='.';
const walls=[];const boxGeo=new THREE.BoxGeometry(1,1,1);
function box(parent,geo,material,pos,scale,cast=true){const o=new THREE.Mesh(geo,material);o.position.set(...pos);o.scale.set(...scale);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o}
// Mansion shell, tiled floors, worn wall blocks and architectural trim.
for(let r=0;r<N;r++)for(let c=0;c<N;c++){const p=world(r,c);if(grid[r][c]==='#'&&!(r===0&&c===11)){const w=box(scene,boxGeo,mWall[(r*7+c*3)%mWall.length],[p.x,1.8,p.z],[CELL,3.8,CELL]);walls.push({x:p.x,z:p.z,hx:2,hz:2});box(scene,boxGeo,mTrim,[p.x,3.72,p.z],[4.05,.16,4.05],false);continue}box(scene,boxGeo,mFloor[(r*3+c*5)%3],[p.x,-.14,p.z],[3.98,.28,3.98],false);box(scene,boxGeo,mDark,[p.x,-.30,p.z],[3.99,.08,3.99],false)}
// Outer plastered ceiling beams and room accents.
const beamMat=mat(0x211d19);for(let z=-20;z<=20;z+=8)box(scene,boxGeo,beamMat,[0,3.72,z],[46,.24,.3],false);
// Sconces give small islands of sickly warm light.
for(const [x,z] of [[-18,-10],[2,-18],[18,-6],[-10,10],[14,14],[0,2]]){const lamp=new THREE.PointLight(0xc28348,7,9,2);lamp.position.set(x,2.4,z);scene.add(lamp);box(scene,boxGeo,mGold,[x,2.75,z],[.18,.24,.18],false)}
// Exit gate: its heavy panel swings open when the lock is turned.
const doorPivot=new THREE.Group();doorPivot.position.set(18.35,0,-23.8);scene.add(doorPivot);const door=box(doorPivot,boxGeo,mat(0x30231c),[1.65,1.6,0],[3.3,3.2,.28]);box(scene,boxGeo,mGold,[20,3.35,-23.8],[3.6,.18,.38],false);for(let x of [18.2,21.8])box(scene,boxGeo,mTrim,[x,1.7,-23.8],[.22,3.4,.4],false);const doorCollision={x:20,z:-23.8,hx:1.55,hz:.55};
// Furniture helpers and scattered mansion relics.
const wood=mat(0x38291f),cloth=mat(0x37302b),bone=mat(0x8a8270);function table(x,z){box(scene,boxGeo,wood,[x,.75,z],[2.3,.16,1.25]);for(const dx of [-.9,.9])for(const dz of [-.4,.4])box(scene,boxGeo,wood,[x+dx,.35,z+dz],[.13,.7,.13])}
table(-14,-4);table(10,8);box(scene,boxGeo,cloth,[2,.56,10],[2.6,1.1,1.3]);box(scene,boxGeo,wood,[-18,.75,2],[1.2,1.5,2.4]);
// Key pedestal and floating blue key.
const keyPos=world(2,10);box(scene,boxGeo,wood,[keyPos.x,.45,keyPos.z],[1.2,.9,1.2]);box(scene,boxGeo,mGold,[keyPos.x,.94,keyPos.z],[1.35,.1,1.35],false);
const keyGroup=new THREE.Group();keyGroup.position.set(keyPos.x,1.38,keyPos.z);scene.add(keyGroup);const blue=new THREE.MeshStandardMaterial({color:0x42aaff,emissive:0x147aff,emissiveIntensity:2,metalness:.65,roughness:.22});const torus=new THREE.Mesh(new THREE.TorusGeometry(.24,.065,8,20),blue);torus.rotation.y=Math.PI/2;keyGroup.add(torus);const stem=box(keyGroup,boxGeo,blue,[.32,0,0],[.5,.1,.1],false);const tooth=box(keyGroup,boxGeo,blue,[.48,-.09,0],[.1,.2,.1],false);const keyGlow=new THREE.PointLight(0x268bff,7,7,2);keyGroup.add(keyGlow);
// Player model: survivor in a dark coat, readable silhouette and shoulder light.
const player=new THREE.Group();scene.add(player);const skin=mat(0xb59072),coat=mat(0x22272b),pants=mat(0x17191c),shirt=mat(0x8c342d),gunMat=mat(0x191d20,.35,.65);
const torso=box(player,boxGeo,coat,[0,1.12,0],[.58,.78,.34]);box(player,boxGeo,shirt,[0,1.37,.19],[.32,.32,.045]);box(player,boxGeo,skin,[0,1.76,.04],[.3,.33,.3]);box(player,boxGeo,mat(0x242321),[0,1.94,.04],[.34,.12,.34]);for(let s of [-1,1]){box(player,boxGeo,coat,[s*.38,1.12,.02],[.2,.65,.22]);box(player,boxGeo,skin,[s*.38,.81,.2],[.14,.16,.13]);box(player,boxGeo,pants,[s*.18,.43,0],[.21,.68,.26]);box(player,boxGeo,mDark,[s*.18,.1,.07],[.23,.18,.38])}box(player,boxGeo,gunMat,[.38,1.05,.48],[.12,.15,.55]);
const playerLight=new THREE.SpotLight(0xffe7c1,95,20,Math.PI/7,.48,1.5);playerLight.position.set(0,1.55,.18);player.add(playerLight);const lightTarget=new THREE.Object3D();lightTarget.position.set(0,.5,8);player.add(lightTarget);playerLight.target=lightTarget;
// Zombie creatures assembled from meshes; their heads and arms sway while they hunt.
const zombies=[];const zSkin=mat(0x68705b),zCloth=mat(0x3c3933),zBlood=mat(0x592c27);function makeZombie(r,c){const g=new THREE.Group();scene.add(g);const head=box(g,boxGeo,zSkin,[0,1.68,.04],[.37,.38,.35]);box(g,boxGeo,zCloth,[0,1.12,0],[.66,.82,.39]);box(g,boxGeo,zBlood,[.08,1.31,.21],[.25,.25,.04]);for(let s of [-1,1]){box(g,boxGeo,zSkin,[s*.43,1.16,.06],[.18,.66,.2]);box(g,boxGeo,zSkin,[s*.18,.45,0],[.23,.72,.28]);const eye=new THREE.Mesh(new THREE.SphereGeometry(.045,8,8),new THREE.MeshBasicMaterial({color:0xd43c22}));eye.position.set(s*.1,1.72,.22);g.add(eye)}const p=world(r,c);g.position.set(p.x,0,p.z);return {g,hp:2,attack:0,walk:Math.random()*5,hpFlash:0}}
makeZombie(6,9);makeZombie(3,2);makeZombie(8,9);
const playerPos=world(10,2);player.position.set(playerPos.x,0,playerPos.z);

