player.position.set(playerPos.x,0,playerPos.z);

// State and input.
let active=false,over=false,hp=100,ammo=6,keyTaken=false,doorOpen=false,shotCooldown=0,damageTimer=0,invuln=0,elapsed=0;
const keysDown=new Set(),joyInput={x:0,y:0},$prompt=$('#prompt');let audio;
function sound(freq,dur,type='triangle',volume=.06){try{if(!audio)audio=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
function setPrompt(text){$prompt.innerHTML=text;$prompt.classList.toggle('show',!!text)}
function startGame(){active=true;over=false;$('#start').classList.add('hidden');$('#end').classList.add('hidden');$('#hud').style.display='block';if(audio?.state==='suspended')audio.resume();}
$('#begin').onclick=()=>{startGame();sound(340,.14)};$('#restart').onclick=()=>location.reload();
window.addEventListener('keydown',e=>{keysDown.add(e.key.toLowerCase());if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.key.toLowerCase()==='e')interact()});window.addEventListener('keyup',e=>keysDown.delete(e.key.toLowerCase()));
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(!active)return;if(e.button===0)shoot();if(e.pointerType==='mouse'&&document.pointerLockElement!==canvas)canvas.requestPointerLock?.()});
let dragX=null;canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse')dragX=e.clientX});window.addEventListener('pointerup',()=>dragX=null);window.addEventListener('pointermove',e=>{if(document.pointerLockElement===canvas)camYaw-=e.movementX*.003;else if(dragX!==null){camYaw-=(e.clientX-dragX)*.006;dragX=e.clientX}});
// Touch joystick and buttons.
const joy=$('#joy');joy.addEventListener('pointerdown',e=>{joy.setPointerCapture(e.pointerId);moveJoy(e)});joy.addEventListener('pointermove',e=>{if(e.buttons)moveJoy(e)});function moveJoy(e){const r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.max(1,Math.hypot(dx,dy)),k=Math.min(1,46/m);joyInput.x=dx/m*k;joyInput.y=dy/m*k}joy.addEventListener('pointerup',()=>{joyInput.x=joyInput.y=0});joy.addEventListener('pointercancel',()=>{joyInput.x=joyInput.y=0});$('#fire').addEventListener('pointerdown',e=>{e.preventDefault();shoot()});$('#interact').onclick=interact;
function dist(a,b){return Math.hypot(a.x-b.x,a.z-b.z)}
function blocked(x,z,r=.38){for(const w of walls)if(Math.abs(x-w.x)<w.hx+r&&Math.abs(z-w.z)<w.hz+r)return true;if(!doorOpen&&Math.abs(x-doorCollision.x)<doorCollision.hx+r&&Math.abs(z-doorCollision.z)<doorCollision.hz+r)return true;return false}
function moveEntity(obj,dx,dz,r=.38){let x=obj.position.x,z=obj.position.z;if(!blocked(x+dx,z,r))x+=dx;if(!blocked(x,z+dz,r))z+=dz;obj.position.x=x;obj.position.z=z}
function gridOf(x,z){return {c:Math.round(x/CELL+6),r:Math.round(z/CELL+6)}}
function nextCell(sx,sz,tx,tz){const s=gridOf(sx,sz),t=gridOf(tx,tz);if(s.r===t.r&&s.c===t.c)return {x:tx,z:tz};const q=[s],seen=new Map([[s.r+','+s.c,null]]);let end=null;for(let i=0;i<q.length;i++){const a=q[i];if(a.r===t.r&&a.c===t.c){end=a;break}for(const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]){const r=a.r+dr,c=a.c+dc,k=r+','+c;if(walk(r,c)&&!seen.has(k)){seen.set(k,a.r+','+a.c);q.push({r,c})}}}if(!end)return {x:tx,z:tz};let k=end.r+','+end.c,prev=seen.get(k);while(prev&&prev!==s.r+','+s.c){k=prev;prev=seen.get(k)}const [r,c]=k.split(',').map(Number),p=world(r,c);return {x:p.x,z:p.z}}
function interact(){if(!active||over)return;const dKey=dist(player.position,keyPos),dDoor=Math.hypot(player.position.x-20,player.position.z+21.4);if(!keyTaken&&dKey<2.1){keyTaken=true;keyGroup.visible=false;$('#keyText').textContent='AZUL';$('#keyText').classList.add('key-chip');$('#objective').textContent='Abra a porta de saída';$('#subObjective').textContent='A chave azul encaixa na fechadura da entrada.';sound(680,.22);setPrompt('');return}if(dDoor<2.4){if(!keyTaken){setPrompt('A porta está trancada — encontre a chave azul');sound(100,.22,'square',.025);return}if(!doorOpen){doorOpen=true;$('#objective').textContent='Escape da mansão';$('#subObjective').textContent='O portão está aberto. Corra!';doorCollision.hx=0;doorPivot.rotation.y=-Math.PI*.48;sound(120,.6,'sawtooth',.06);setPrompt('');return}finish(true)}}
function finish(win){over=true;active=false;document.exitPointerLock?.();$('#end').classList.remove('hidden');$('#endEyebrow').textContent=win?'VOCÊ SOBREVIVEU':'FIM DE JOGO';$('#endTitle').textContent=win?'Amanhecer':'A mansão venceu';$('#endText').textContent=win?'A porta se fecha atrás de você. O silêncio ficou para os mortos.':'Você caiu nos corredores escuros. Talvez da próxima vez encontre a chave antes que eles encontrem você.';sound(win?520:70,.65,win?'sine':'sawtooth',.08)}
function shoot(){if(!active||over||shotCooldown>0)return;if(ammo<=0){sound(90,.08,'square',.025);return}ammo--;shotCooldown=.42;$('#ammoText').innerHTML=String(ammo).padStart(2,'0')+' <span style="color:#777;font-size:13px">/ 06</span>';sound(75,.12,'square',.1);sound(38,.22,'sawtooth',.04);
 let target=null,best=18;const fx=Math.sin(camYaw),fz=Math.cos(camYaw);for(const z of zombies){if(z.hp<=0)continue;const dx=z.g.position.x-player.position.x,dz=z.g.position.z-player.position.z,d=Math.hypot(dx,dz),dot=(dx*fx+dz*fz)/Math.max(d,.001),side=Math.abs(dx*fz-dz*fx);if(dot>0&&side<.72&&d<best){best=d;target=z}}if(target){target.hp--;target.hpFlash=.13;target.g.rotation.y=camYaw+Math.PI;sound(210,.08,'triangle',.04);if(target.hp<=0){target.g.visible=false;sound(130,.2,'sawtooth',.035)}}}

